 static final String OPERATOR=uuid();
 /** A second human with recall RECORD/close capabilities but no ADMIN or MANAGER decision authority. */
 void operator(){jdbc.update("INSERT INTO mulino_identity_Actors(organizationId,ID,kind,stableRequestOwner) VALUES(?,?,'HUMAN',?)",ORG,OPERATOR,OPERATOR);jdbc.update("INSERT INTO mulino_identity_ExternalIdentities(organizationId,ID,actorId,issuer,subject,organizationAlias) VALUES(?,?,?,'https://fixture.invalid','operator','ORG-A')",ORG,uuid(),OPERATOR);jdbc.update("INSERT INTO mulino_identity_Memberships(organizationId,ID,actorId,validFrom,validUntil) VALUES(?,?,?,CURRENT_TIMESTAMP-INTERVAL '1 day',CURRENT_TIMESTAMP+INTERVAL '1 day')",ORG,uuid(),OPERATOR);String grant=uuid();jdbc.update("INSERT INTO mulino_identity_Grants(organizationId,ID,actorId,delegatorId,validFrom,validUntil) VALUES(?,?,?,?,CURRENT_TIMESTAMP-INTERVAL '1 day',CURRENT_TIMESTAMP+INTERVAL '1 day')",ORG,grant,OPERATOR,OPERATOR);jdbc.update("INSERT INTO mulino_identity_GrantScopes VALUES(?,?,'ORGANIZATION',?)",ORG,grant,ORG);jdbc.update("INSERT INTO mulino_identity_AuthorityFences VALUES(?,?,1)",ORG,OPERATOR);
  var caps=new ArrayList<>(CAPS);caps.addAll(List.of("getEvidence","disposeQuantity"));for(String cap:caps){jdbc.update("INSERT INTO mulino_identity_CapabilityAssignments(organizationId,ID,actorId,capabilityId,scopeKind,scopeId,validFrom,validUntil) VALUES(?,?,?,?,'ORGANIZATION',?,CURRENT_TIMESTAMP-INTERVAL '1 day',CURRENT_TIMESTAMP+INTERVAL '1 day')",ORG,uuid(),OPERATOR,cap,ORG);jdbc.update("INSERT INTO mulino_identity_GrantActions VALUES(?,?,?)",ORG,grant,cap);}}
 Map<String,Object> asOperator(String cap,Map<String,Object> slots){var recorder=SecurityContextHolder.getContext().getAuthentication();SecurityContextHolder.getContext().setAuthentication(new org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken(org.springframework.security.oauth2.jwt.Jwt.withTokenValue("local-test-context").header("alg","RS256").issuer("https://fixture.invalid").subject("operator").claim("organizationId","ORG-A").build(),List.of()));try{return recall(cap,slots);}finally{SecurityContextHolder.getContext().setAuthentication(recorder);}}
 String code(Map<String,Object> result){return String.valueOf(((Map<?,?>)result.get("error")).get("code"));}
 int closures(){return jdbc.queryForObject("SELECT count(*) FROM mulino_trade_recall_Closures WHERE investigationId=?",Integer.class,investigation);}
 int actions(String kind){return jdbc.queryForObject("SELECT count(*) FROM mulino_trade_recall_Actions WHERE kind=?",Integer.class,kind);}
 java.math.BigDecimal partitionValue(Map<String,Object> effects,String key){return new java.math.BigDecimal(((Map<?,?>)effects.get("partition")).get(key).toString());}

 /** Finding 0: recovery recorded under v1 stays a fact after an ADMIN re-scope; v2 can dispose it and close truthfully. */
 @Test void rescopeAfterRecoveryCarriesPhysicalFactsAndClosesTruthfully(){
  open();propose("25");approve();String leaf=effects(recall("recordRecovery",proof("RECOVERED","0","25",segment,Map.of()).slots())).get("currentSegmentId").toString();
  propose("50");approve();
  var again=recall("recordRecovery",proof("RECOVERED","0","25",leaf,Map.of()).slots());assertEquals("CONFLICT",again.get("outcome"),again.toString());assertEquals("RECALL_RANGE_ALREADY_RECOVERED",code(again));assertEquals(1,actions("RECOVERED"));
  var disposed=effects(recall("recordRecovery",proof("DISPOSED","0","25",leaf,Map.of()).slots()));
  assertEquals(0,new java.math.BigDecimal("25").compareTo(partitionValue(disposed,"DISPOSED")));assertEquals(0,new java.math.BigDecimal("25").compareTo(partitionValue(disposed,"RECOVERED")));assertEquals(0,new java.math.BigDecimal("25").compareTo(partitionValue(disposed,"UNKNOWN")));
  assertEquals(0,new java.math.BigDecimal("35").compareTo(jdbc.queryForObject("SELECT SUM(quantity) FROM mulino_inventory_QuantitySegments WHERE retiredAt IS NULL",java.math.BigDecimal.class)));
  // Excluded 25–60 of v1 still has its open human review; v2's excluded 50–60 is not a second duty for the same units.
  assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM mulino_work_read_ObligationReferences WHERE kind='RECALL_EXCLUDED_SCOPE' AND valid AND workId=?",Integer.class,WORK));
  var exception=effects(recall("recordRecovery",proof("EXCEPTION","25","25",null,Map.of("reason","Verified unreachable customer evidence and explicit ADMIN exception")).slots()));assertEquals(0,partitionValue(exception,"UNKNOWN").signum());
  var closure=proof("CLOSURE","0","50",null,Map.of("partitionHash",exception.get("partitionHash")));var closed=effects(recall("closeRecall",Map.of("scopeId",scope,"scopeHash",scopeHash,"approvalId",approval,"canonicalOccurrenceId",closure.canonical(),"partitionHash",exception.get("partitionHash"))));
  assertEquals("25",((Map<?,?>)closed.get("partition")).get("DISPOSED").toString());assertEquals("25",((Map<?,?>)closed.get("partition")).get("EXCEPTION").toString());assertEquals(1,closures());}

 /** Finding 7: a range disposed under v1 is DISPOSED under v2 and cannot be relabelled SAFE or CONSUMED_LOST. */
 @Test void disposalUnderEarlierVersionStaysDisposedAndBlocksContradictoryTerminalLabels(){
  open();propose("50");approve();String leaf=effects(recall("recordRecovery",proof("RECOVERED","0","25",segment,Map.of()).slots())).get("currentSegmentId").toString();effects(recall("recordRecovery",proof("DISPOSED","0","25",leaf,Map.of()).slots()));
  propose("40");approve();
  var safe=recall("recordRecovery",proof("SAFE","0","25",null,Map.of()).slots());assertEquals("HELD",safe.get("outcome"),safe.toString());assertEquals("RECALL_PARTITION_CONFLICT",code(safe));
  var lost=recall("recordRecovery",proof("CONSUMED_LOST","10","10",null,Map.of()).slots());assertEquals("HELD",lost.get("outcome"),lost.toString());assertEquals("RECALL_PARTITION_CONFLICT",code(lost));
  assertEquals(0,actions("SAFE")+actions("CONSUMED_LOST"));
  var rest=effects(recall("recordRecovery",proof("SAFE","25","15",null,Map.of()).slots()));assertEquals(0,new java.math.BigDecimal("25").compareTo(partitionValue(rest,"DISPOSED")));assertEquals(0,partitionValue(rest,"UNKNOWN").signum());}

