 /** Finding 5: the current actor's ADMIN authority gates EXCEPTION and closure; the approver's authority is not borrowed. */
 @Test void nonAdminCannotRecordExceptionOrCloseRecall(){
  operator();open();propose("50");approve();var exceptionProof=proof("EXCEPTION","0","50",null,Map.of("reason","Approved unresolved exact customer scope"));
  var denied=asOperator("recordRecovery",exceptionProof.slots());assertEquals("REJECTED",denied.get("outcome"),denied.toString());assertEquals("FORBIDDEN",code(denied));assertEquals(0,count("mulino_trade_recall_Actions"));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM mulino_work_read_ObligationReferences WHERE kind='RECALL_EXCEPTION_RESIDUAL' AND workId=?",Integer.class,WORK));
  var result=effects(recall("recordRecovery",exceptionProof.slots()));var closure=proof("CLOSURE","0","50",null,Map.of("partitionHash",result.get("partitionHash")));var close=Map.<String,Object>of("scopeId",scope,"scopeHash",scopeHash,"approvalId",approval,"canonicalOccurrenceId",closure.canonical(),"partitionHash",result.get("partitionHash"));
  var closeDenied=asOperator("closeRecall",close);assertEquals("REJECTED",closeDenied.get("outcome"),closeDenied.toString());assertEquals("FORBIDDEN",code(closeDenied));assertEquals(0,closures());
  effects(recall("closeRecall",close));assertEquals(1,closures());}

 /** Finding 3: historical reads derive investigation state from immutable rows known at knownAt. */
 @org.springframework.beans.factory.annotation.Autowired com.mulino.application.trade.recall.RecallQueries recallQueries;
 Map<?,?> read(Instant knownAt){var c=new DomainContext(ORG,ACTOR,OWNER,Instant.now(),knownAt);return (Map<?,?>)request(()->recallQueries.query(c,new QueryRequest("getRecall",investigation,Map.of("objectType","Recall"),Map.of(),50,null,null,c.asOf(),c.knownAt(),null))).data();}
 @Test void historicalRecallReadsUseStateKnownAtThatTime() throws Exception{
  open();Thread.sleep(20);Instant beforeScope=Instant.now();Thread.sleep(20);propose("50");approve();
  var early=read(beforeScope);assertEquals("INVESTIGATING",early.get("status"),early.toString());assertNull(early.get("currentScopeId"));assertNull(early.get("partition"));
  var list=request(()->{var c=new DomainContext(ORG,ACTOR,OWNER,Instant.now(),beforeScope);return recallQueries.query(c,new QueryRequest("getRecalls",null,Map.of("objectType","Recall","workId",WORK),Map.of(),50,null,null,c.asOf(),c.knownAt(),null));});assertEquals(1,((List<?>)list.data()).size());
  var result=effects(recall("recordRecovery",proof("EXCEPTION","0","50",null,Map.of("reason","Approved unresolved exact customer scope")).slots()));Thread.sleep(20);Instant beforeClose=Instant.now();Thread.sleep(20);
  var closure=proof("CLOSURE","0","50",null,Map.of("partitionHash",result.get("partitionHash")));effects(recall("closeRecall",Map.of("scopeId",scope,"scopeHash",scopeHash,"approvalId",approval,"canonicalOccurrenceId",closure.canonical(),"partitionHash",result.get("partitionHash"))));
  var open=read(beforeClose);assertEquals("APPROVED",open.get("status"),open.toString());assertNull(open.get("closedAt"));assertEquals(scope,open.get("currentScopeId"));
  var now=read(Instant.now());assertEquals("CLOSED",now.get("status"));assertNotNull(now.get("closedAt"));}

 /** Unverified P3-0: an EXCEPTION residual gets its own future next check, so a stale investigation check cannot block closure. */
 @Test void exceptionResidualCarriesItsOwnFutureNextCheck(){
  open();propose("50");approve();jdbc.update("UPDATE mulino_trade_recall_Investigations SET nextCheckAt=CURRENT_TIMESTAMP-INTERVAL '1 minute' WHERE ID=?",investigation);
  var exceptionProof=proof("EXCEPTION","0","50",null,Map.of("reason","Approved unresolved exact customer scope"));
  var stale=recall("recordRecovery",exceptionProof.slots());assertEquals("REJECTED",stale.get("outcome"),stale.toString());assertEquals(0,count("mulino_trade_recall_Actions"));
  var slots=new LinkedHashMap<>(exceptionProof.slots());slots.put("nextAction","Locate remaining customer stock");slots.put("nextCheckAt",Instant.now().plusSeconds(7200).toString());var result=effects(recall("recordRecovery",slots));
  var closure=proof("CLOSURE","0","50",null,Map.of("partitionHash",result.get("partitionHash")));effects(recall("closeRecall",Map.of("scopeId",scope,"scopeHash",scopeHash,"approvalId",approval,"canonicalOccurrenceId",closure.canonical(),"partitionHash",result.get("partitionHash"))));
  assertEquals("Locate remaining customer stock",jdbc.queryForObject("SELECT nextAction FROM mulino_work_read_ObligationReferences WHERE ID=?",String.class,result.get("residualDutyId")));}
